    background: "崇祯朝面临着全球小冰期带来的连年绝收巨灾，陕北干旱人相食，饥民揭竿而起席卷中原；同时朝廷为应付辽东与剿匪连年加派三饷，导致小农经济全面崩溃，官逼民反恶性循环。崇祯十七年初，李自成在西安称帝建大顺政权后挥师东渡黄河，明朝地方卫所与边军望风而降，京畿门户大开，终酿成大明中枢覆亡的甲申剧变。",
