    interpretation: "曹石之变表面是功臣谋反，实则是皇权与拥立功臣结构性矛盾的总爆发。英宗以兵变复辟，得位本非正途，故对拥立者既倚重又猜疑；石亨、曹吉祥不知自抑，反恃从龙之功要挟君上、钳制言路，覆亡只是迟早之事。英宗先借石彪案剪其羽翼，再以逯杲密侦施压，待其自乱阵脚而后诛之，手段老辣而从容。此变更暴露出明代宦官典兵的积弊：曹吉祥以司礼太监提督三大营，私蓄降丁数百，几成腹心之患，为后世刘瑾、魏忠贤之专权开一先例。而于谦之冤终在成化初平反，亦说明守国柱石终不被历史埋没。",
