    interpretation: "东林党争的深层逻辑，是明代皇权高度集中之后士大夫议政空间的萎缩与反弹。神宗怠政二十余年，内阁与六部运转失灵，官员只能以书院清议和门户结盟表达政见，“朋党”由贬称变成了实际的政治组织方式。东林争国本、争三大案，确有正大之气；但天启朝皇权落入魏忠贤之手，士大夫失去体制内的屏障，只能以肉身对抗诏狱酷刑。六君子、后七君子之死是晚明士风的绝响，也证明“清议”无法转化为有效制度。黄宗羲后来在《明夷待访录》中主张学校应为议政机关，正是对东林悲剧的思想回应；而“明亡于党争”之叹，至今仍是读史者绕不开的题目。",
