          "南宫门禁森严，锦衣卫校尉日夜轮值，外臣不得入觐，英宗与外界几乎断绝。宫中供给亦时见克减，景泰帝又曾命尽伐南宫树木，英宗无荫可庇，兄弟猜忌已成死结。七年之间，昔日天子沦为朝野讳言之人；而幽禁越是严密，石亨等人日后迎立的空间与「反正」的名义就越充足。太上皇的存在本身，成了景泰朝最危险的一柄悬剑。"
