          "景泰八年（1457年）正月初，帝病势转沉，罢郊祀、辍朝不视事。十四日，群臣合疏请早建东宫，帝勉强表态，仍无定论。武清侯石亨奉诏入宫探视帝疾，见帝沉疴难起，料大位将空，遂起异心：若仍遵诏复立见深，自己不过捧诏之臣；若迎太上皇复位，则为再造功臣。他随即与太监曹吉祥、都督张軏、都察院左副都御史徐有贞暗通款曲，兴济伯杨善、学士许彬、赵荣等预其事。",
          "徐有贞原名徐珵，正统末年倡言南迁，为于谦所斥，久不得志，遂改名图进，且精于星历占候。他夜观天象，以「天命有归」之说鼓动同党，众议遂决。正月十六日夜，众人聚于徐有贞宅中，定计以翌日五更动手，分头布置。"
