          "一行至奉天殿，时天尚未明，太上皇升座，鸣钟鼓，开诸门。百官闻钟声仓皇入朝，至丹墀，见御座上所坐者竟是太上皇，无不震悚。徐有贞出班大呼「上皇复位矣」，百官遂叩首朝贺。正月十七日（公历1457年2月11日），英宗朱祁镇重登大宝，颁诏天下，改景泰八年为天顺元年。",
          "同日，景泰帝被废为郕王，迁居西苑（西宫）。据《明史》所载，石亨等行事前曾密白皇太后孙氏，得太后允准，遂使这场武力政变披上「奉旨」的合法外衣。然而宫门一夜易主，朝堂之上更大的血腥才刚刚拉开序幕。"
