      {
        heading: "大掠八日，饮恨城下",
        paragraphs: [
          "俺答此来本为以兵逼贡，无意攻城。蒙古军在城外盘踞八日，焚庐舍，掠人畜，凡金银布帛、工匠妇女，捆载以去，被掳男女不可胜计。八月二十一日前后，俺答押解满载辎重，由白羊口（今北京延庆西北）徐徐出塞。仇鸾率兵尾随，不敢击其前锋，仅击其后卫老弱，斩数十级以充功，世宗竟下诏嘉奖。京师解严后，世宗追责御边无状，兵部尚书丁汝夔下狱弃市；丁汝夔临刑大呼“嵩误我”，而严嵩终未受惩。",
          "俺答虽退，索贡益急。世宗迫于形势，于嘉靖三十年（1551年）三月诏开马市于大同、宣府，以仇鸾主其事。然明朝君臣仍以通贡为耻，马市旋开旋停，俺答失望之余复纵兵深入。直至隆庆五年（1571年），明穆宗与内阁大学士张居正等力排众议，封俺答为顺义王，通贡互市，北边始得数十年安宁。而庚戌之变中冒功得宠的仇鸾，终以私通蒙古、贪功败露，于嘉靖三十一年（1552年）病死后被戮尸枭示。"
        ]
      }
