    interpretation: "庚戌之变看似偶发边患，实为明朝中期制度积弊的一次总爆发。卫所制败坏，军屯被占，兵丁逃亡过半，九边形同虚设；京营久为权贵占役，操练尽废，故十万之众不堪一战。朝堂之上，严嵩以“寇饱自去”误国，边将以贿赂取将位，上下相蒙。世宗于礼制争论中精明，于国防实务却懵懂，杀丁汝夔不过塞责。俺答以战促贡，终在隆庆五年（1571年）促成封贡，说明通贡互市本合双方利益；明廷昧于大势，一意拒贡，徒令京畿遭屠。此役之后，戚继光等将领受命北上练兵，北方边防整顿由此开端。",
