    interpretation: "国本之争表面为储位继承之争，实质是皇权与文官集团的制度性对抗。神宗以待嫡为名、行立爱之实，群臣以宗法长子制与祖训为凭，以贬谪廷杖为代价，前仆后继，两不相下。十五年相持，两败俱伤：皇权因怠政自弃威信，文官集团在抗争中聚合为东林，门户攻讦由是而兴。太子虽立而地位未安，梃击、红丸、移宫三案接踵，泰昌一月天子即殂，皆国本未固之祸。万历三大征虽胜而国库虚耗，建州女真乘隙崛起。故《明史》论「明之亡，实亡于神宗」，十五年之争，正是明室由盛转衰的枢纽所在。",
