          "然而严刑峻法自有代价。数万官吏死于追赃株连，中产之家大抵破败，士人视出仕为畏途。朱元璋晚年似亦有所省察，曾在诏令中告诫臣下勿再深刻罗织。建文帝即位后宽刑省狱，永乐以降刑政渐平，但洪武朝重典所留下的君臣猜忌与官场震荡，仍长久地影响着明代政治，成为后世难以释怀的一段酷烈记忆。"
