    summary: "泰昌元年（1620年）八月，明光宗朱常洛即位仅十日即患重病，鸿胪寺丞李可灼进红丸，光宗连服二丸，翌日清晨暴崩于乾清宫，在位仅一月，年三十九岁。新君壮年骤殁，朝野震骇，御史、给事中交章追论进药之责，矛头直指首辅方从哲、司礼监太监崔文升及郑贵妃一党。此案与此前梃击案、其后移宫案并称明末三案，是晚明宫廷阴谋与党争交织的枢纽事件，其纷争一直延续到天启、崇祯两朝。",
    background: "万历一朝，围绕皇位继承的国本之争持续多年。神宗朱翊钧宠爱郑贵妃，欲立其子福王朱常洵为储，群臣坚请立皇长子朱常洛，争执十余年，至万历二十九年（1601年）朱常洛方册立为太子。此后太子如履薄冰，万历四十三年（1615年）又发生张差持梃闯入慈庆宫之梃击案，朝野多疑为郑贵妃主使，宫廷暗流始终未息。万历四十八年（1620年）七月二十一日，神宗驾崩。八月，朱常洛即位，颁诏改元泰昌，发内帑银犒赏辽东边军，补阁部缺员，朝纲颇有更始之望。然光宗即位仅十日即不豫：郑贵妃进美女数人侍寝，光宗体气本虚，遂至委顿；司礼监秉笔太监崔文升本出郑贵妃宫中，又掌御药房，进大黄泻药，致光宗泄泻不止，病势骤危。廷臣疑惧，疑郑贵妃欲害新君以保福王，京师人心惶惶。",
    chapters: [
      {
        heading: "帝疾骤危",
        paragraphs: [
          "万历四十八年七月二十一日，明神宗朱翊钧崩于弘德殿，皇太子朱常洛以八月朔日即皇帝位，颁诏大赦，以八月以后为泰昌元年。新君登极之初，颇示革新之意：发内帑银一百万两犒赏辽东将士，尽罢矿税、榷税中使，起用建言获罪诸臣，一时中外欣然，望治甚殷。然光宗年已三十有九，潜邸四十年，忧谗畏讥，身体素弱。即位仅十日，便即不豫，不能视朝，政事悉委之内阁与司礼监。",
          "光宗病起，与郑贵妃所进美女颇有干系。郑贵妃于光宗即位后，选美姬数人进御，光宗连日宴饮承欢，精力渐不能支。至八月中旬，病势转沉。司礼监秉笔太监崔文升原在郑贵妃宫中当差，光宗即位后令其掌御药房，崔文升竟进大黄之剂。大黄性寒，本为攻下之药，施于虚损之人，适足促其寿。光宗服后，一昼夜泄泻数十次，委顿床褥，不能起立。外廷闻之，兵科给事中杨涟、左光斗等交章弹劾崔文升，谓其用药无状，必受主使，乞穷治其罪。",
          "八月二十九日，光宗病笃，御乾清宫东暖阁，召见内阁首辅方从哲、大学士韩爌、刘一燝、吏部尚书周嘉谟等大臣十三人。光宗凭几而坐，谕以辅立皇长子朱由校，令群臣尽心辅佐；又问及寿宫陵寝之事，群臣惶恐，莫敢遽对。召对之际，鸿胪寺丞李可灼至，自云有仙方可以疗帝疾。所谓仙方者，乃以红铅、秋石、人乳、辰砂等物炼制的红丸，本道家服食之术，非对症之药。"
        ]
      },
      {
        heading: "红丸下咽",
        paragraphs: [
          "李可灼官鸿胪寺丞，品秩虽卑，而以方药自进。其所进红丸，又名红铅丸，以妇人经水炼取之红铅为主，佐以秋石、人乳、辰砂，色赤如丹，故称红丸。方从哲等大臣以为药不可轻进，宜令御医详察。光宗求生心切，急欲服之。先服一丸，自言暖润舒畅，思进饮食，左右皆喜，以为有效；遂复进一丸。方从哲在侧，诘问可灼所进何药，可灼以仙丹对，语多夸诞。",
          "孰料服下第二丸后，光宗状况急转直下。翌日即九月初一日五更，宫中传凶信：光宗崩于乾清宫。自八月初一日登极至九月初一日驾崩，在位恰满一月，寿三十有九，庙号光宗。凶闻传出，举朝震骇：新君以壮年御极，旬日之间由病而崩，且恰值连服红丸之后，进药之李可灼、主使嫌疑之郑贵妃一党、在侧之首辅大臣，皆成众矢之的。"
        ]
      },
      {
        heading: "追论纷起",
        paragraphs: [
          "光宗崩，皇长子朱由校即位，明年改元天启。御史王安舜首上疏，劾李可灼以无方无制之药，妄言仙丹，轻投冲昧之主，请置之法；给事中惠世扬追论方从哲，谓其身为首辅，进药之时在侧不谏，又拟旨赏李可灼银五十两、币二，是纵贼弑君，罪不可逭。南京诸臣亦纷起响应，请诛崔文升、李可灼。方从哲连疏乞罢，天启帝慰留之，令李可灼回籍，崔文升发遣南京。",
          "红丸一案，与张差梃击慈庆宫之梃击案、李选侍据乾清宫之移宫案，先后相接，合称明末三案。三案皆围绕皇位传承，牵涉郑贵妃、福王与东林党，门户之见与宫闱之争互相缠绕。齐、楚、浙三党与东林党各自借三案攻讦对手，是非淆乱。方从哲终在天启四年（1624年）致仕归里，而三案之争未已。",
          "天启中后期，魏忠贤勾结客氏，擅权乱政，借三案翻局：杀杨涟、左光斗、魏大中等东林党人，炮制《三朝要典》，颠倒三案是非，凡当年追论红丸、移宫之臣，多遭迫害。崇祯帝即位，诛魏忠贤，毁《三朝要典》，阉党伏法，红丸案之论争方告平息。然明王朝亦在这无休止的内耗中走向末路。"
        ]
      }
    ],
    interpretation: "红丸案的关键，不在药之真伪，而在皇权更迭之际制度与程序的失序。光宗以三十九岁壮年即位，旬日而亡，考其实，当是本元久虚、又遭纵欲伤身，崔文升误下大黄，泄尽元气；红丸以红铅、秋石燥烈之品投于垂绝之人，遂成催命之符。未必是蓄意鸩杀，但进药无御医勘验、无内阁公议，草率如此，则阴谋论必然滋生。方从哲以首辅在侧，不能裁抑，反拟旨赏赐，其责难辞；而群臣穷追不舍，亦杂以门户之争。三案相连，把万历朝国本之争的怨毒带入天启、崇祯两朝，终明之世，纷纭难解。",
