    dynasty: "明",
    era: "弘治元年",
    year: {
      start: 1488
    },
    summary: "弘治中兴指明孝宗朱祐樘在位十八年（1488—1505）间出现的治世局面。孝宗即位后斥逐成化朝佞幸，罢黜传奉官，广开言路，恢复经筵与午朝；倚重刘健、李东阳、谢迁三位阁臣同心辅政，简拔马文升、刘大夏、戴珊等干吏整饬吏治、治理黄河、绥靖边防，朝政为之一清。史家将其与仁宣之治并称，视为明代中叶政治最清明、社会最安定的时期。《明史》谓太祖、成祖而外可称者惟仁宗、宣宗、孝宗，故曰中兴。",
    background: "成化后期朝政积弊深重。万贵妃宠冠后宫，其弟万喜与内官梁芳、僧人继晓、术士李孜省交通弄权；传奉官不经吏部铨选，由内旨直接任命，至成化末年积至数千员，文武冗滥。阁臣万安、刘吉、刘珝碌碌保位，时人讥为纸糊三阁老，六部尚书则称泥塑六尚书。皇庄侵占京畿民田，荆襄流民屡聚屡平而根源未除。朱祐樘的幼年尤为坎坷：生母纪氏本为宫中女史，怀孕后遭万贵妃逼害，赖被废的吴皇后与内侍张敏暗中保全，生于安乐堂，六岁方得见父皇，成化十一年立为太子，不久纪氏暴卒。险恶的宫廷环境，使他即位后格外体恤下情、痛恨佞幸，以廓清积弊为急务。",
    chapters: [
      {
        heading: "廓清成化积弊",
        paragraphs: [
          "弘治元年（1488）正月，朱祐樘即位改元，时年十八岁。即位诏书颁下当日，便将成化朝权倾朝野的佞幸一一处置：术士李孜省谪戍，不久瘐死；僧人继晓斩于市；万贵妃之弟万喜与内官梁芳下狱，籍没家产，家属充军。同时宣布裁汰传奉官——成化朝由内旨直接任命、不经吏部铨选的传奉官已积至数千员，诏令凡由此途进身者一律罢斥。仅此一项，京师冗官为之一空。孝宗幼年生于安乐堂，六岁方得见父，生母纪氏又离奇暴卒，故于成化朝弊政有切肤之痛，登基伊始即以扫清积弊为急务。",
          "新政第二桩是广开言路。孝宗即位后下诏求言，许科道官与朝臣指陈时政得失，不究妄言。他恢复经筵，命儒臣定期进讲经史，虽寒暑风雨不辍；又重开午朝，于早朝之外在午门临轩听政，召见部院大臣面议庶务。如此则皇帝不再仅凭章奏与内阁知天下事，近侍亦难于壅蔽。成化末年讥为纸糊三阁老的万安、刘吉、刘珝，至是相继罢去；成化间因建言直谏得罪的官员，亦多起复录用，朝堂风气为之一变。",
          "孝宗持身俭素，禁内廷供奉珍玩。成化间内府采办珍珠、猫睛、绿玉等物岁靡民财，弘治元年即下诏停罢各处采办，放还进贡番夷。皇庄之制始于成化，侵占京畿民田，孝宗虽未能尽革，但屡诏禁止额外侵占，并减免顺天、保定等地庄田租额。凡遇水旱蝗灾，辄下诏免赋、发仓赈济。自幼长于忧患的皇帝，对民间疾苦有异于寻常天子的体察，这成为弘治一朝宽厚为政的底色。"
        ]
      },
      {
        heading: "任贤图治",
        paragraphs: [
          "弘治朝中枢，以内阁刘健、李东阳、谢迁三人最为倚重。刘健为首席大学士，刚介端凝，临大事有断；李东阳学问渊深，长于谋议与文章；谢迁机敏善辩，应对捷给。三人同心辅政，时人有李公谋、刘公断、谢公尤侃侃之誉。六部尚书亦多一时之选：马文升历官兵部、吏部尚书，整饬军伍，威行边塞；刘大夏以都御史、兵部尚书两度治河典兵；戴珊掌都察院，风纪肃然；何乔新、彭韶、周经等并以清直著称。孝宗推心委任，奏章多即日批答，阁部得行其志。",
          "弘治五年（1492），黄河决口冲毁张秋运道，朝廷震动。孝宗命工部右侍郎刘大夏前往治理。刘大夏先疏浚汴河、睢河等旧道，分杀水势，随后堵塞张秋决口，沿河筑太行堤三百六十余里。至弘治八年（1495）工成，黄河复归故道，南北运河畅通无阻，沿河州县得免水患，此次治河被视为明代水利史上最成功的工程之一。同年西北亦有捷报：土鲁番速檀阿黑麻于弘治元年攻占哈密，俘忠顺王罕慎；马文升决策用兵，遣甘肃巡抚许进、总兵刘宁出塞，克复哈密，重立卫所，西北边防为之一振。",
          "内政方面，孝宗屡申吏治考核之令。弘治初年清查天下军职冗员，裁汰冒滥；又令各地抚按考察郡县，贪酷者即时劾罢。弘治十五年（1502），《大明会典》修成，凡一百八十卷，将洪武以来典章制度汇为一编，颁示中外，使政务有所遵依。弘治一朝，赋役有所减免，府库渐见充盈，社会安定，户口渐增，荆襄山区流民亦陆续附籍安业。经历成化朝的因循之后，国家重新回到有序运转的轨道。"
        ]
      },
      {
        heading: "宫壶肃清与暮年",
        paragraphs: [
          "孝宗的宫廷生活为历代帝王所无：他一生仅张皇后一人，未册立一妃一嫔。张氏是大兴（今属北京）人，成化二十三年（1487）册为皇太子妃，同年孝宗即位立为皇后。帝后同起同居，如民间夫妇。孝宗曾患病辍朝，张后亲奉汤药；外戚张鹤龄、张延龄虽封侯拜伯，孝宗约束严格，不许干预朝政，有犯亦绳之以法。一夫一妻的后宫，使弘治朝杜绝了成化朝万贵妃式的宫廷干政，也省却无数倾轧。",
          "弘治十八年（1505）五月初七，孝宗病逝于乾清宫，年三十六岁。弥留之际，召大学士刘健、李东阳、谢迁与兵部尚书刘大夏等至榻前，受遗命辅佐太子朱厚照。遗诏中告诫太子讲学亲贤、任用大臣，又嘱咐司礼监勿令左右近诱帝嬉游。葬于泰陵（今北京昌平天寿山），庙号孝宗。太子即位，改元正德，是为武宗。孝宗以盛年骤崩，主少国疑，弘治朝苦心经营的清明政治，此后不过数年便告瓦解。"
        ]
      }
    ],
    interpretation: "弘治中兴的本质，是人治的巅峰而非制度的创新。明代皇权不受制约，孝宗以个人的勤勉与宽厚弥补体制缺陷：宦官、外戚、阁臣之间的平衡，全系于帝王一身的手腕与自律。土木之变后，成化朝的怠政已暴露皇权独大的弊端；弘治朝证明贤君可以致小康，却未能从根本上约束皇权。故孝宗一崩，武宗即恣意放纵，刘瑾等八虎乱政，弘治旧臣或贬或罢，正应了其人存则政举、其人亡则政息。但弘治十八年确实给了社会休养生息之机，户口渐增，运河畅通，边防复振，为正德、嘉靖两朝社会经济的延续发展奠定了基础。",
