    interpretation: "己巳之变的症结，不仅在军事，更在政治。皇太极绕道入关，证明单靠宁锦一线无法护持京畿，明朝“守关外以蔽关内”的战略露出致命破绽；蓟镇虚备，实为百余年来重辽轻蓟、文恬武嬉之积弊。袁崇焕之死，则是崇祯朝政治崩坏的缩影：君主多疑而刚愎，廷臣门户角立，袁崇焕擅杀毛文龙在先，早已结怨朝议；皇太极的反间计，不过是压垮他的最后一根稻草。后金借此次入塞窥破明朝虚实，掠得大量人口物资，更确立了斫其枝干、耗其根本的长期方略。明朝既失长城之将，又添流寇之患，内外交困，国运遂绝。袁崇焕之冤，直至清修《明史》披露反间计始末，方大白于天下。",
