    summary: "洪武九年（1376年），朱元璋发现地方官员赴京呈报钱谷册时，惯常携带预先盖好官印的空白文册，以便户部驳正后就地填改。他认定其中必有侵欺舞弊，遂兴大狱，凡主印官员坐死，佐贰以下杖一百、戍远方，被诛者数以百计，清廉如济宁知府方克勤亦死于是狱。此案是洪武四大案中起因最暖昧、后世争议最大的一案，既见元末以来相沿的衙门积习，也见明初以重典治吏的峻烈之风。",
    background: "明初定鼎，天下赋税、钱谷、军需之数，每年由各布政使司、府、州、县层层造册，遣吏赴京送户部核校。按定制，册上数字须与户部所掌完全一致，方准奏销；若有丝毫参差，户部即行驳正，发回重造。重造之册须重新盖印，而地方印信掌于长官之手，往返动辄数月，驿传所费不赀。为省时省费，自元末以来，府州县吏便沿一旧习：临行前先备若干盖有完整官印的空白文册，携至京师，待户部核出何项数字不符，便就地填注改定，免却千里折返。此法上下皆知，户部亦默许其事，相沿成俗，本非一朝一夕之弊。洪武九年，天下考校钱谷策册，空白文册之习终于惊动朱元璋。他出身寒微，素恨吏胥欺蒙，见册上官印赫然而字迹可任意填写，断定此中必有通同侵盗、虚增妄报之弊，于是雷霆骤作，一案倾动天下。其所由生，是制度僵滞与君王猜忌相激相乘的结果。",
    chapters: [
      {
        heading: "空印何来",
        paragraphs: [
          "明初财政，以册籍为纲。每年岁终，各布政使司并所属府、州、县，须将本处钱谷、户口、军需诸项造具清册，差遣官吏赍赴京师，送户部比对核校。定制极严：册内每一项数字，须与户部账簿分毫不差，方能销账；稍有出入，户部即加驳正，发回原衙门重造。重造之册须再经地方长官用印，始为有效。",
          "中国幅员辽阔，远省如云南、四川，往返京师动逾数月，甚至经年。一册驳回，再造再行，又需数月，往往今年之账，明年尚未了结；驿传供应、吏员守候，皆耗公帑累民力。于是自元代即有变通之法：地方官府预先备办若干空白文册，逐页钤盖官印，带入京师，一旦户部驳出某项不符，便就驻京之地依驳改填，省却往返之劳。",
          "此法行之既久，户部与地方彼此会意，视若常例。在衙门看来，不过是图办事便捷；在制度上，它却使册籍之核校流于形式——数字可以事后填写，则上报之数是否属实，全凭填册之人操守。此正为空印案伏下的祸根。"
        ]
      },
      {
        heading: "雷霆忽作",
        paragraphs: [
          "洪武九年（1376年），天下考校钱谷策册，空白印册之事上闻。朱元璋览之大怒，以为官印乃朝廷信守，空白文册在手，欲填何数便填何数，钱谷出入尽由其便，上下通同，欺罔朝廷，必有侵盗冒支之弊，遂下令穷治。一时之间，自布政使司至府州县，凡案册涉及空印者，悉数逮问。",
          "治罪之法极为严酷：凡衙门主印之官，即掌印长官，不论知情与否，一律处死；佐贰以下属官，杖一百，充军远方边卫。据后世如方孝孺《先府君行状》等记载推算，坐死之主印官数以百计，杖戍者不可胜数。一时州县正官为之一空，吏员股栗，京外大震。",
          "济宁知府方克勤之死，最见此案之酷。方克勤为官方正，布衣蔬食，济宁户口滋殖，治行冠于山东，曾受朝廷旌表。其属吏以空印文册赴部，事觉牵连，克勤亦下狱论死。其子方孝孺后来追述父冤，字字血泪，为后世留下了此案最沉痛的个人记录。"
        ]
      },
      {
        heading: "一书难回",
        paragraphs: [
          "举朝皆知空印多为办事旧习，非尽舞弊，然狱怒方盛，廷臣钳口，无敢言者。唯浙江黄岩人郑士利，其兄郑士元时为湖广按察司佥事，坐空印事系狱。士利待兄狱解之后，愤而上书，洋洋数千言，力辩空印之非罪。",
          "郑士利之书，大意谓：空印文册，乃元代相沿之旧规，并非国初新设；州县距京远者数千里，若数字偶有驳正，必待发回重造，则官吏奔走无已时，故携空印以备用，实为权宜，非有他心。且钱谷之数，府申布政司，布政司申部，层层查核，岂能尽凭一册空文行奸？纵有奸吏，当治其实犯，不应一概株连。书入，朱元璋愈怒，以其淆乱章法，竟将郑士利谪戍江浦，以示惩戒。",
          "自郑士利一书见拒，朝堂遂更无谏者。数百官员伏诛于一时，空印之习自此尽绝，州县造册虽严而畏惧之心过于谨慎之实。朱元璋以一己之断，行非常之罚，其意本在惩贪墨、肃纲纪，而案中冤滥，终不可掩，故后世论者多以为此乃洪武年间用法太过之明验。"
        ]
      }
    ],
    interpretation: "空印案之深层，是制度僵滞与君权雷霆的正面相撞。地方钱谷核驳之制，本意在于上下稽察，杜绝侵欺；但定制不恤道里之远、往返之久，逼出空印这一变通之法，户部默许，上下相安，说明积习已成，非一衙一门之过。朱元璋不问情由，将相沿之惯例径断为通同舞弊，以主印者死、佐贰杖戍之重罚，一案而诛数百官员，其治吏之酷，可谓至极。此案最可深味之处，在于冤滥与整肃并存：空印确为奸蠹留有可乘之隙，然坐死之人多为奉公守土之官，方克勤、郑士元之属，清正者亦不免骈首就戮。郑士利上书见拒，说明洪武一朝言路峻窄，士大夫但知畏法，不敢论理。此案与胡惟庸案、蓝玉案先后相仍，共成明初重典治吏之局，使百官惴惴，州县凛然，吏治为之一肃，而士大夫持禄保身之风亦由此渐起，其影响远在案狱本身之外。",
