      {
        heading: "逆臣录颁，余波未平",
        paragraphs: [
          "洪武二十六年九月，太祖命辑录案犯供词，编为《逆臣录》，颁示天下，亲为之序，宣称诛此乱臣贼子以安宗社。此案与十三年前胡惟庸案前后相继，并称「胡蓝之狱」，两案合计株连四万五千余人。经此二狱，明初分封的功臣宿将几乎诛戮殆尽，公侯仅存数人，且多战栗自保，不敢预事，朝堂为之一空。",
          "武勋集团的覆灭，直接改变了明朝此后的军事格局。建文帝即位后，朝中已无可用之宿将，靖难之役起，以耿炳文、李景隆统兵，皆非燕王朱棣之敌，终致南京陷落，帝位易主。蓝玉案表面是一场平叛，实质是皇权对功臣集团的一次彻底整肃，其影响远超一时一案，成为明初政治由武功转向文治的关键转折。"
        ]
      }
