    interpretation: "蓝玉案之实质，是朱元璋为身后布局的一次政治大清洗。太子朱标早逝，皇太孙幼弱，功臣宿将手握重兵，太祖遂采狡兔死、走狗烹之策，借蓝玉之桀骜，罗织成狱，一举芟除整个武勋集团。就帝王权术而言，此案确乎消除了尾大不掉之忧，皇权空前强化；然其代价同样沉重：能征善战之将帅诛戮殆尽，卫所精锐失其统率，建文朝坐拥天下之兵，竟不能敌燕王一隅之师，终有靖难之变。后世论者多以为此案实属冤狱，所谓谋反，据供状屈打成招，不足为凭。观《逆臣录》之颁，警示群臣、钳制功臣之意昭然若揭。胡蓝之狱后，勋臣武将再难制衡皇权，有明一代君权独大之局，由此奠定。",
