          "崇祯九年（1636）七月，高迎祥在陕西盩厔黑水峪遭陕西巡抚孙传庭伏击，兵败被俘，押解北京遇害，李自成被诸部推举为闯王。崇祯十一年（1638），洪承畴、孙传庭合力围剿，李自成在潼关南原陷入重围，大败之余，仅刘宗敏等十八骑遁入商洛山中，农民战争陷入低潮。崇祯十三年（1640），河南大旱，蝗灾蔽天，赤地千里。李自成趁机出商洛山，进入河南，开仓赈济，饥民从者如流，众至数十万。史载其部伍所至不妄杀、不淫掠，发富室仓廪以赈饥民，又令军中为谣曰“吃他娘，穿他娘，闯王来时不纳粮”，“均田免赋”之说由此传遍中原。"
