          "崇祯十七年（1644）正月，李自成在西安建国，国号大顺，改元永昌，封功臣，开科举，补州县官，以牛金星为大学士，政权规模初具。随即兵分两路东征：刘宗敏率一路自山西平阳北上，李自成亲率一路经太原、大同、宣府，直指京师。沿途州县或降或溃，明文武官员望风而遁，大同总兵姜瓖、宣府总兵王承胤相继投降。三月十七日，大顺军进抵北京城下，环攻九门。十八日夜，彰义门为宦官开启（开门者何人，史籍记载不一），十九日凌晨，北京陷落。"
