          "四月，李自成亲率大军征讨吴三桂，二十一日战于山海关一片石。吴三桂已暗通清摄政王多尔衮，双方合击，清军铁骑趁大风骤至，大顺军先胜后败，全线崩溃。李自成退回北京，四月二十九日在武英殿匆匆即位，三十日焚宫撤出，经山西退回关中；清军尾随入关，定鼎北京。此后大顺军屡战屡败，先失潼关、西安，再退湖广。顺治二年（1645）五月，李自成率部行至湖北通山九宫山，遭乡兵袭杀（其死因自缢、战死、误杀诸说并存，主流从通山遇害说）。余部由李过、高一功率领，后联明抗清，大顺政权遂告终结。"
