    interpretation: "李自成起义的迅速壮大，根子不在军事而在财政与土地。明末三饷加派把赋税压在贫苦小民头上，宗室勋贵与缙绅地主却享有优免特权，土地兼并空前严重，“均田免赋”正是这一社会矛盾的集中反映。起义军能“迎闯王，不纳粮”，靠的是打击宗藩、没收富室赈济饥民，因而获得底层支持。但其失败同样深刻：大顺军长于流动作战，始终未建立稳固的根据地与财政体系，入京后拷掠士绅追赃助饷，将本可争取的缙绅阶层推向对立；对关外清军的战力与意图缺乏清醒判断，山海关一败便不可收拾。崇祯帝之死与明朝之亡，并非一人一事之失，而是整个王朝治理体系崩溃的结果。",
