    dynasty: "明",
    era: "隆庆五年",
    year: {
      start: 1571
    },
    summary: "隆庆五年（1571）三月，明朝封蒙古右翼土默特部首领俺答汗为顺义王，并开放大同、宣府等处马市，与蒙古通贡互市。自洪武元年（1368）元廷北遁，明蒙对峙已逾二百年，其间有土木之变、庚戌之变等大战，边祸连连。和议成后，东起辽海，西至嘉峪，烽燧顿熄，边境安靖者数十年，且为万历初年张居正整饬内政创造了难得的外部环境。此事史称隆庆和议，又称俺答封贡，是明朝处理边疆民族关系最为成功的一次实践。",
    background: "明蒙世仇，根植于南北对峙的结构。洪武元年（1368）元顺帝北遁，蒙古退回草原，明朝修长城、列九边，以防守为务；蒙古各部分裂为鞑靼、瓦剌，却屡屡南下。正统十四年（1449）土木堡之变，英宗被俘，二十万明军精锐尽丧；嘉靖二十九年（1550）庚戌之变，俺答率军破古北口，直逼北京城下，大掠京畿而去。此后二十年，俺答岁岁犯边，九边防线岁岁告急。其实俺答并非一味好战：嘉靖二十年（1541）起，他多次遣使求贡，愿以马匹换取中原的粮食、布匹与铁锅；明朝厉行封锁，甚至杀其使臣石天爵。越封锁，蒙古越匮乏；越匮乏，越要南下抄掠；越抄掠，明朝越拒绝通商——双方陷入死循环。至隆庆四年（1570），俺答已六十四岁，部众疲敝；其孙把汉那吉因家事愤而降明，遂为打破僵局提供了转机。是时高拱、张居正柄政，王崇古任宣大山西总督，方逢时任大同巡抚，边臣得人，朝局清明，和议之机已臻成熟。",
    chapters: [
      {
        heading: "把汉那吉叩关",
        paragraphs: [
          "隆庆四年（1570）十月，俺答之孙把汉那吉偕其妻与乳母之夫阿力哥等十余人，至大同叩关请降。把汉那吉为俺答第三子铁背台吉之子，幼年丧父，由俺答之妻一克哈屯抚养成人。他本已聘定一部长之女，俺答却将新纳之妇钟金哈屯（即三娘子）许配与他，旋即自纳之，且夺其原配之妻。把汉那吉羞愤交加，遂决意南奔。宣大山西总督王崇古、大同巡抚方逢时深知此乃千载良机，力排众议受降，奏请授把汉那吉指挥使，赏赐甚厚，使居大同。朝中多有非议，谓其必为祸端，王崇古不为所动。",
          "消息传至草原，俺答大惊，率十万骑犯大同，扬言索孙。王崇古临危不乱，遣使驰入俺答营中，晓以利害：若开战，则把汉那吉必不保；若愿归款通贡，则送孙归，且许开马市。俺答妻一克哈屯亦日夜哭孙不休。俺答本无意与明朝死战，闻使臣之言大喜，遂遣使至大同议和。王崇古即上疏朝廷，请因势利导，许其封贡。疏上，朝议纷然：御史饶仁侃、武尚贤等力言不可，惧其为也先故事之续；高拱、张居正却力主乘机一决，鼎力支持王崇古。明穆宗从后一种意见。",
          "明朝遂定计：以把汉那吉为筹码，促俺答归款。俺答为示诚意，执汉人逃民赵全等九人献于明。赵全本白莲教党，逃入草原后为俺答策划犯边多年，明朝悬赏缉拿已久。俺答既缚献赵全，明朝亦遣使送把汉那吉北还，祖孙相聚，泣谢而去。至此，双方互信既立，封贡之议遂定。一桩因家事而起的风波，竟演为明朝与蒙古右翼之间的和平契约。"
        ]
      },
      {
        heading: "顺义王受封",
        paragraphs: [
          "隆庆五年（1571）三月，明朝遣使至大同边外，俺答率其子弟部众设坛歃血，对天立誓永不犯边。明朝正式册封俺答为顺义王，赐金印、蟒衣；其弟昆都力哈、长子黄台吉以下六十余人，各授都督同知、指挥使、千户等官，岁给赏赐。俺答时年六十五岁，受封后上表谢恩，自称大明属臣，许以世世进贡，不绝和好。自此，俺答部自嘉靖二十九年以来二十余年的战争状态，正式宣告结束。",
          "同年，明朝于大同、宣府、山西、宁夏、延绥等镇开放马市。市分官、民二种：官市由官府主持，以茶、布、铁器、丝绸易蒙古马匹；民市则听边民与蒙古牧民交易，各取所需。王崇古手定市约，严禁抢劫、走私及夹带违禁物品，违者由俺答自行惩治。俺答严格执行，部下有犯边者即斩以徇；明朝边将亦约束士卒，两境帖然。俺答又请于青海、甘肃开市，明朝亦许之，互市遂遍于九边。"
        ]
      },
      {
        heading: "边烽顿熄",
        paragraphs: [
          "和议既成，其效立现。自隆庆五年至明末，东起辽海，西至嘉峪，蒙古诸部再无大规模犯塞之举。沿边荒土渐次开垦，汉蒙杂居之地生齿日繁，六畜遍野。张家口、得胜堡、水泉营等马市所在，渐次繁盛为商埠：内地布匹、茶叶、铁锅、丝绸源源北去，蒙古马匹、皮毛、牛羊南来，百货流通，税课渐丰。俺答晚年倾心佛法，万历六年（1578）迎三世达赖喇嘛至青海仰华寺会面，黄教由是大兴于蒙古草原，部众杀伐之风渐减。",
          "俺答于万历十年（1582）病逝，明朝遣使致祭，赙赠甚厚。其妻三娘子（明朝封忠顺夫人）继承其志，约束部众，历配顺义王三代，维系和局近四十年。万历间张居正柄国，藉此安定的边防，整饬吏治，清丈田亩，推行一条鞭法，国库渐充。史家论之，谓隆庆一朝虽享国日浅，而北边款服、海宇承平，为万历初政创造了难得的外部环境，实为明朝国势之一大转机。"
        ]
      }
    ],
    interpretation: "隆庆和议之所以能成，在于双方都已厌倦战争，且各有所求：蒙古需要中原的粮食、布匹与铁器，明朝需要边境的安宁。把汉那吉降明不过是一个偶然契机，真正的推手是王崇古、方逢时的远略，与高拱、张居正的庙堂决断。它证明：互市通商、各取所需，往往比修筑长城、穷兵黩武则更能消弭边患。自洪武至嘉靖，明朝对蒙古或征或守，耗费无数，终未得安；而隆庆一朝以封王开市四字，便换来了数十年和平。其局限在于，和局维系于俺答、三娘子等首领个人之力，一旦人事更迭，和平即难为继——明末后金崛起，林丹汗西迁，宣大互市再度动荡。但就其时代而言，隆庆和议仍是传统王朝处理边疆民族关系最成功的一次实践。",
