    interpretation: "南北榜案之本质，非科场舞弊之案，而是地域政治之争。朱元璋未必不知南卷文字优于北卷，张信等覆阅之结论亦未必阿私；帝所不能忍者，乃“一榜尽南人”之局所隐含的政治风险。北方为防御北元之根本，士人若绝望于仕进，则离心离德，国本不固。故此案之裁决，实为政治裁决而非司法裁决——以数考官之死、一主考之戍，换北方六十一人之登第、北士之归心。其深远影响，在于确立“以地域配额调节取士”之原则：洪熙、宣德间南北分卷成为会试定制，清代分省中额即其遗意。科举由此兼具选才与整合双重功能，此案正其枢纽。",
