    summary: "南明抗清，指崇祯十七年（1644）北京陷落后，明朝宗室与文武臣僚在南方相继建立弘光、隆武、绍武、永历等政权，联合农民军余部与海上力量抗击清军的历史进程。前后历时十八年，历经史可法扬州殉国、李定国两蹶名王、郑成功北伐与收复台湾等大事，终以永历帝被绞杀于昆明告终。它是明朝的尾声，也是明清易代中最为惨烈悲壮的一页。",
    background: "崇祯十七年（1644）三月，李自成率领的大顺军攻入北京，思宗朱由检自缢于煤山，立国二百七十六年的明朝宣告覆亡。然而明朝实行两京之制，南京作为留都，设有一套完整的六部、都察院与五军都督府班底；江南赋税重地未遭战火，为明祚延续提供了制度与物质基础。北方局势瞬息万变：大顺政权立足未稳，镇守山海关的总兵吴三桂引清军入关，多尔衮率八旗于一片石击败李自成，随即定鼎北京，以「复君父之仇」为名南下，其志实在天下。消息传至江南，拥立新君成为第一要务；崇祯三子皆陷于北方，皇位继承只能在藩王中展开，纷争由此而起。",
    chapters: [
      {
        heading: "金陵残梦：弘光与扬州",
        paragraphs: [
          "崇祯十七年（1644）五月，福王朱由崧在南京即位，改明年为弘光元年，朝政却落入马士英、阮大铖之手，东林、复社诸臣遭斥逐；江北四镇黄得功、高杰、刘良佐、刘泽清各拥重兵，互相攻伐。大学士史可法受排挤，出镇扬州、督师江北，号令不出军门。弘光朝君臣但求偏安，未能趁清军主力未下之际北进，坐失时机。",
          "弘光元年（清顺治二年，1645）四月，清豫亲王多铎率军南下，直指扬州。史可法檄调各镇援兵，无一至者。四月二十五日，扬州城破，史可法自刎未死，为清军所执，劝降不屈，遂遇害。清军入城后屠戮十日，死者数十万，史称「扬州十日」。五月，南京文武献城出降，弘光帝在逃亡途中被俘，旋押解北京处死。江南半壁，传檄而定。"
        ]
      },
      {
        heading: "闽海风云：隆武与绍武",
        paragraphs: [
          "南京陷落后，顺治二年（1645）闰六月，唐王朱聿键在郑芝龙、黄道周等拥戴下于福州即位，改元隆武。隆武帝素有恢复之志，即位后整军经武，欲亲赴湖广督师，然兵权尽在郑芝龙之手，终受其挟制。大学士黄道周以书生募兵出江西，兵败婺源，被俘殉国。顺治三年（1646）八月，隆武帝在汀州被清军擒获，绝食而死于福州。同时浙东鲁王朱以海在绍兴以监国称制，与隆武政权互争正统，甚至兵戎相见，抗清力量大为削弱。",
          "顺治三年十一月，隆武帝之弟朱聿𨮁在广州称帝，改元绍武；桂王朱由榔亦在肇庆即位，改元永历。两个政权并为争正统而交兵，绍武立国仅四十余日，即为清将李成栋所灭，朱聿𨮁自缢殉国。广东既失，永历政权遂成南明最后一线余脉，自此辗转于西南边陲。"
        ]
      },
      {
        heading: "西南烽火：永历十八年",
        paragraphs: [
          "永历帝朱由榔即位之初即颠沛流离，自肇庆而梧州、全州、武冈，数年间播迁于广西、贵州、云南之间。瞿式耜留守桂林，何腾蛟经营湖广，独撑危局。顺治六年（1649），何腾蛟兵败湘潭，殉国；顺治七年十一月，桂林陷落，瞿式耜端坐衙中，与总督张同敞同被执，赋诗不绝，不屈而死。永历朝廷几无立锥之地。",
          "危急之际，大顺军余部李过、高一功、李来亨与大西军孙可望、李定国相继联明抗清。顺治九年（1652），李定国自云南出师，东入广西，攻克桂林，清定南王孔有德举火自焚；转战湖南，又于衡阳阵斩清敬谨亲王尼堪，两蹶名王，天下震动，清廷一度有弃西南七省之议。然孙可望嫉妒定国之功，内讧日烈。顺治十四年，孙可望兵败降清，尽以虚实告之，清军遂三路入滇。",
          "顺治十五年（1658），清信郡王多尼率军入云南，永历帝逃入缅甸。顺治十八年（1661），吴三桂率兵入缅，迫缅人交出永历帝。康熙元年（1662）四月，永历帝父子被绞杀于昆明篦子坡，南明亡。自弘光立国至此，凡十八年。"
        ]
      },
      {
        heading: "海上长城：金厦与台湾",
        paragraphs: [
          "郑成功初名森，福建南安人，隆武帝曾赐姓朱，故称「国姓爷」。其父郑芝龙降清，成功不从，焚儒服，起兵南澳，遥奉永历正朔。他以金门、厦门为基地，建立前后左右五军，修船练兵，屡挫清军于海上。顺治十五年（1658），郑成功大举北伐，翌年六月入长江，破瓜洲、镇江，直抵南京城下；张煌言别部深入芜湖，传檄而反正者四府三州二十四县，江南震动。七月，郑军轻敌中伏，败于南京城下，退回金厦，北伐功亏一篑。",
          "顺治十八年（1661），郑成功率军二万五千人、战船数百艘横渡台湾海峡，经鹿耳门入台江，围荷兰殖民者于热兰遮城。次年二月，荷兰长官揆一出降，台湾收复。郑成功在台湾设府县、兴农练兵，使之成为延续明朔的最后基地。永历朝廷覆亡后，郑氏仍奉永历纪年不改，直到康熙二十二年（1683）郑克塽降清，明朔始绝。"
        ]
      }
    ],
    interpretation: "南明坐拥半壁江山、百万之众，终告覆亡，其败因不在一端：皇室统绪断绝，诸王争立，各建旗帜甚至同室操戈；军镇武人化，四镇与诸将拥兵自重，朝廷号令不行；党争未因国难稍戢，弘光朝马阮之祸、永历朝孙李之争，皆自毁长城；又兼财用枯竭，饷尽援绝。然南明抗清牵制清军主力近二十年，使西南、东南得保汉家衣冠；史可法、瞿式耜、张煌言以身殉国，郑成功复台而开东南新局，其气节与事功，早已超越了成败本身。",
