    interpretation: "宁远之胜，其要在三：凭坚城、用重炮、励死士。自萨尔浒至广宁，明军屡败，非兵不多、将不勇，而在于野战不敌、城守不固、中枢失策。袁崇焕以孤城当倾国之师，先清野使敌无所获，复以红夷大炮居高临下，破其楯车云梯之旧法，使后金骑兵之长尽失于坚城之下。此为后金起兵以来首次攻坚战受挫，其士气与战略皆受震动。然宁远一捷并未扭转双方强弱之大势，觉华岛粮储尽失，辽西已伤其根本；且捷后叙功，阉党冒赏、孙承宗见逐，朝局掣肘如故，袁崇焕终不免于崇祯之祸。后人于此，见火器与城守结合之效，亦见明末事权不一、功臣难安之弊。胜败之机，固在疆场，亦在庙堂。",
