    background: "万历初年，张居正任内阁首辅，推行考成法与一条边鞭法，太仓存银一度积至四百万两以上，国力为之一振。万历十年（1582）张居正病逝，神宗亲政，未几即怠于理政，奏疏多留中不发，部院缺官不补。其时北方俺答封贡，长城沿线战事消歇；东南倭患经戚继光、俞大猷剿平已久，明朝本可休养生息。然环顾四境，危机正暗暗酝酿：日本关白丰臣秀吉于万历十八年（1590）统一日本，野心直指朝鲜乃至大明辽东；西南播州宣慰使杨应龙世袭二十九代，骄横跋扈，屡叛屡降；西北宁夏降将哱拜久居边镇，私蓄苍头军，与文官积怨日深。三大征正是在这府库尚有余财而危机四伏的承平表象之下接连爆发的。",
