          "战争掏空的不仅是国库，更是国运。辽东精锐久驻朝鲜，给了建州女真首领努尔哈赤吞并各部的空隙；军费枯竭使九边欠饷成为常态，将士寒心。万历四十六年（1618）努尔哈赤以七大恨告天伐明，明军仓促应战，翌年萨尔浒一役三路丧师，精锐尽覆，明朝从此转入守势，直至亡国。三大征的胜利，恰是明朝最后一场体面的胜利。"
