    interpretation: "三大征是对明朝军事与财政体系的一次总检验。卫所制早已败坏，作战主力转为临时招募的边镇精兵与将领私兵——李如松的辽东铁骑、戚继光留下的浙兵、刘綎的川兵——胜负系于名将调度，而非制度运转。财政上，三场战争把张居正十年改革攒下的家底一扫而空，岁入四百万两的朝廷被迫以矿税、辽饷饮鸩止渴，催饷的鞭子最终抽向百姓，民变四起。战略上，明军虽赢得三场边境战争，却在随后的二十年里输掉了整个天下：努尔哈赤趁辽东空虚崛起，萨尔浒惨败接踵而至。故《明史》论断「明之亡，实亡于神宗」，三大征正是这一转折的起点。",
