          "马哈木依山布阵，以骑兵居高冲击。朱棣命柳升率神机营先发，火铳、神机箭轮番齐射，瓦剌骑兵人马纷披；安远侯柳升、武安侯郑亨继以步骑合击，宁阳侯陈懋、成山侯王通各率精骑包抄两翼。瓦剌大败，马哈木遁去，王子数十人被俘。",
          "此役是明军火器与骑兵、步兵协同作战的典型战例。朱棣进兵至土拉河，因粮饷将尽下令班师。马哈木次年遣使谢罪贡马，瓦剌暂服，朱棣则封瓦剌三部首领为王，分而制之，草原再度形成均势。"
