    summary: "泰昌元年（1620年）九月初一，明光宗朱常洛即位仅一月便驾崩。光宗宠妃李选侍（西李）挟持皇长子朱由校据守乾清宫，意图争得皇贵妃乃至太后名分。兵科给事中杨涟、御史左光斗等联合司礼监太监王安，于九月初二将朱由校自暖阁中抢出；九月初五又以唐武后之祸为戒，逼李选侍移居哕鸾宫。九月初六朱由校即位，改元天启，是为明熹宗。移宫案与梃击案、红丸案并称明末三大案，直接开启了天启朝东林党与魏忠贤阉党的激烈党争。",
    background: "万历四十八年（1620年）七月二十一日，在位四十八年的明神宗驾崩。八月初一，皇太子朱常洛登基，诏改元泰昌。朱常洛一生备受国本之争困扰，神宗宠爱郑贵妃，久不欲立其为太子；即位后郑贵妃进献美姬，光宗沉湎其中，仅一月便一病不起。光宗宠妃李选侍（西李）随居乾清宫，并抚养丧母的皇长子朱由校——朱由校生母王才人于万历四十七年病故，李选侍遂以抚养之名挟制皇长子。光宗病重之际，李选侍要求封皇贵妃甚至皇后，光宗于暖阁召见首辅方从哲等大臣时含糊应允，引发朝臣警觉。九月初一凌晨，光宗服鸿胪寺丞李可灼所进红丸后驾崩，乾清宫顿成权力真空。按明制，乾清宫为皇帝正寝，新君当于此居住即位；李选侍据宫不出，皇长子无法入宫，局势一触即发。",
    chapters: [
      {
        heading: "一月天子，西李据宫",
        paragraphs: [
          "泰昌元年八月初一，三十九岁的朱常洛在文华殿即位，颁诏赦天下，改元泰昌。即位之初，他发内帑银一百万两犒赏辽东边军，补发外官俸禄，颇有振作之意。然而郑贵妃进献八名美姬，光宗连日宴饮，未及半月便病倒。八月二十九日，鸿胪寺丞李可灼进红丸，光宗服后于九月初一日凌晨驾崩，在位仅二十九日，史称一月天子。",
          "光宗即位后，李选侍随居乾清宫。乾清宫是皇帝正寝，李选侍以皇长子抚养者身份盘踞其中。朱由校生于万历三十三年（1605年），其生母王才人位份不高，又于万历四十七年病故，朱由校自幼由李选侍照看，与乳母客氏、太监魏忠贤亲近。光宗病危时曾在暖阁召见首辅方从哲等十三位大臣，李选侍立于帷幕后；光宗欲封李选侍为皇贵妃，李选侍不满足，公然催逼封皇后，群臣愕然。",
          "按照明制，皇帝驾崩后嗣君应即位于乾清宫，而李选侍以陪伴先帝梓宫为名拒绝迁出，朱由校被困宫中。首辅方从哲态度暧昧，企图调和；兵科给事中杨涟、御史左光斗等则认为，李选侍若得逞，将重演汉吕后、唐武后故事，必须以最快速度夺回皇长子，方能保住大明皇统。"
        ]
      },
      {
        heading: "暖阁夺储，朝臣死诤",
        paragraphs: [
          "九月初二，群臣入乾清宫哭临。太监王安与杨涟、刘一燝、周嘉谟等约定，借哭临之机抢出朱由校。李选侍将朱由校藏于暖阁，王安入内哄骗，称文华殿百官迎驾，朱由校脱身而出。杨涟、刘一燝左右护卫，李选侍急呼太监追夺，太监扯住朱由校衣袖，杨涟怒斥之。群臣簇拥皇长子至文华殿，接受百官山呼，朱由校被暂安置于慈庆宫。",
          "同日，左光斗上疏，指出选侍既非嫡母又非生母，却居住乾清宫正寝，而皇长子居偏宫，名分颠倒；他直陈武氏之祸不可不戒，请李选侍即刻移宫。疏入，李选侍大怒。九月初三，杨涟、周嘉谟等面见李选侍，要求其移居哕鸾宫，遭到拒绝。方从哲主张缓行，杨涟力争，认为先帝尸骨未寒，若迁延至新君即位之后，李选侍挟皇长子以自重，朝臣再无办法。",
          "九月初四，李选侍仍据宫不出，京师传言其欲效仿郑贵妃旧事拖延待变。司礼监太监王安等入宫催促，李选侍自知势孤，且皇长子已被朝臣控制，遂被迫应允。九月初五，李选侍怀抱皇八妹迁出乾清宫，移居哕鸾宫。乾清宫遂空出，朱由校移入，皇权交接的最后一道障碍就此扫除。"
        ]
      },
      {
        heading: "熹宗登极，余波未平",
        paragraphs: [
          "九月初六，朱由校在皇极殿即位，颁诏以明年为天启元年，是为明熹宗。即位之初，朝臣本欲既往不咎。然而不久御史贾继春上疏，称移宫之举使先帝骨肉乖离，请厚待李选侍；杨涟等东林党人予以驳斥。熹宗下旨斥责贾继春，并公布李选侍曾殴伤其生母王才人旧事，贾继春削籍归乡，移宫遂成定局。",
          "天启初年，东林党人因拥立定策之功尽据要津，杨涟官至左副都御史，左光斗任佥都御史。然而朱由校自幼依赖乳母客氏与太监魏忠贤，二人渐掌司礼监与东厂。魏忠贤早年出自李选侍宫中，移宫案中站在李选侍一侧；天启三年后，他借封疆、汪文言诸案构陷东林党，又将移宫案翻作旧账。",
          "天启四年（1624年），杨涟上疏弹劾魏忠贤二十四大罪，左光斗等人相继下狱，天启五年先后死于诏狱。魏忠贤追论移宫案，诬杨涟等贪功妄动，起用贾继春。崇祯帝即位后诛魏忠贤、钦定逆案，移宫功臣得以平反，杨涟、左光斗赠谧复官。然明朝已在党争与辽东战事的双重消耗中走向末路，熹宗之弟朱由检最终自缢煤山。"
        ]
      }
    ],
    interpretation: "移宫案表面是宫廷居住之争，实质是皇权交接之际的制度危机。乾清宫乃皇帝正寝，居宫者即居权力正位；李选侍以抚养皇长子为筹码，效仿郑贵妃当年留居乾清宫的先例，试图在权力真空期搏取皇贵妃乃至太后之尊。杨涟、左光斗等人的果断，使明朝避免出现太后临朝或后妃干政的局面，皇长子得以在礼制之内顺利完成即位。但移宫也暴露出东林党人的局限：他们以名分大义相号召，却未能在制度上限制内廷与宦官。熹宗即位后，客氏、魏忠贤以皇帝旧人身份崛起，移宫功臣杨涟、左光斗反死于诏狱，追论旧案成为阉党打击异己的工具。明末三大案由此从宫廷事件演变为党争武器，加速了明朝的衰亡。",
