    interpretation: "迁都北京，是朱棣以雄主之权完成的地缘战略重构。元室北遁之后，长城一线是明朝最脆弱的战区，皇帝亲驻前沿，可直接指挥九边重兵，将帝国最精锐的军队与最庞大的漕粮体系压向北方，“天子守国门”由此成为定式。代价同样沉重：岁输数百万石的漕粮与运河岁修，贯穿有明一代，皆为财政重负；京师远离财赋渊薮，漕路一断，京师立见恐慌，政治中心与经济中心长期分离，江南赋役独重。就长远而言，北京自元大都再兴，历明、清两代，连续六百年为统一王朝的政治中心；紫禁城中轴与坛庙格局，至今仍是首都城市面貌的底色。",
